import Foundation

final class SafeCounter: @unchecked Sendable {
    private let queue = DispatchQueue(label: "counter.serial")
    private var value = 0
    func increment() {
        queue.sync {
            value += 1
        }
    }
    func get() -> Int {
        queue.sync {
            value
        }
    }
}

let counter = SafeCounter()
counter.increment()
counter.increment()
counter.increment()
print("Counter: \(counter.get())")

import Foundation

final class NameRegistry: @unchecked Sendable {
    private let queue = DispatchQueue(label: "registry.queue")
    private var names: [String] = []
    func register(_ name: String) {
        queue.sync {
            names.append(name)
        }
    }
    func allNames() -> [String] {
        queue.sync {
            names
        }
    }
}

let registry = NameRegistry()
registry.register("Alice")
registry.register("Bob")
print("Names: \(registry.allNames().joined(separator: ", "))")

import Foundation

final class JobQueue: @unchecked Sendable {
    private let queue = DispatchQueue(label: "jobs.serial")
    private var completedJobs: Int = 0
    func completeJob() {
        queue.sync {
            completedJobs += 1
        }
    }
    func count() -> Int {
        queue.sync {
            completedJobs
        }
    }
}

let jobQueue = JobQueue()
jobQueue.completeJob()
jobQueue.completeJob()
print("Jobs done: \(jobQueue.count())")
